#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
const int MAX_SIZE = 100001;

#define int long long

int a, b, limit;
double min_difference = 1e9;
int numerator_result, denominator_result;

int lcm(int a, int b) {
    return a * b / __gcd(a, b);
}

int main() {
    cin >> a >> b >> limit;
    if (b <= limit) {
        while (__gcd(a, b) > 1) {
            int g = __gcd(a, b);
            a /= g;
            b /= g;
        }
        cout << a << "/" << b;
        return 0;
    }
    for (int i = 1; i <= limit; i++) {
        int l = lcm(i, b);
        int w = a * (l / b);
        double diff1 = (double)(w - ((w / (l / i)) * (l / i))) / (double)l;
        if (min_difference > diff1) {
            min_difference = diff1;
            numerator_result = (w / (l / i));
            denominator_result = i;
        }
        int num = w + (l / i) - 1;
        int den = (l / i);
        double diff2 = (double)abs(w - (((num) / den) * den)) / (double)l;
        if (min_difference > diff2) {
            min_difference = diff2;
            numerator_result = (num / den);
            denominator_result = i;
        }
    }
    int g = __gcd(numerator_result, denominator_result);
    numerator_result /= g;
    denominator_result /= g;
    cout << numerator_result << "/" << denominator_result;
}
